def refs():
    return [{**s, "subject": "english", "locator": "short research sharing, source use, audience, evidence, and response", "observedPattern": "公開英文評量常以公告、短文、網路資訊與生活任務測量主旨、證據、來源、行動與表達；本題只取能力方向。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]

def make(i, prompt, options, answer, explanation, strategy, steps, difficulty):
    return {"id": f"question-english-performance-6-iv-6-{i}", "subject": "english", "type": "single-choice", "prompt": prompt, "options": [{"id": k, "text": v} for k, v in options.items()], "knowledgeIds": [KG], "difficulty": difficulty, "answer": {"value": answer, "explanation": explanation}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0]["url"], "sourceLocator": "三份公立學校公開英文評量僅供網路／課外資源分享、證據組織與資訊判讀的能力方向研究；未複製原題、選項、文章或答案。", "authoringNote": "依官方課綱 KG 與三筆公開英文試題的資料分享能力方向獨立改寫；素材、選項、解析與轉移任務均為原創，待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-09", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}

Q = [
make(1, "A student wants to share a short report about bicycle safety. Which opening best tells the audience the topic and purpose?", {"A": "Today I will explain two safe cycling habits and why they matter.", "B": "I found a website yesterday.", "C": "Bicycles can be many colors.", "D": "Please look at my title only."}, "A", "A names the topic, the scope of two habits, and the purpose of explaining why they matter.", "分享開場要讓受眾知道主題、範圍與分享目的，不只報告找到網站。", ["找出任務是 bicycle safety 的 short report。", "檢查各選項是否包含 topic、scope 與 purpose。", "確認 A 有 safe cycling habits 與 why they matter。", "排除 B、C、D，因為它們只有來源、零散細節或指令。", "選 A，確認聽眾一開始就能掌握報告方向。"], "easy"),
make(2, "Which source note is most useful when sharing a fact from an online article?", {"A": "Article title, author or organization, URL, and access date.", "B": "Only a copied sentence with no source.", "C": "The website's background color.", "D": "A friend's guess about the fact."}, "A", "These details let the audience identify and check the source of the shared fact.", "分享網路資料要保存可追溯的來源識別，而不是只複製內容。", ["確認任務是分享 online article 的 fact。", "列出 audience 需要回查的來源資訊。", "檢查 A 有 title、author／organization、URL 與 date。", "排除 B、C、D，因為它們不能辨識或驗證原始資料。", "選 A，確認分享內容與來源可以連結。"], "easy"),
make(3, "A student found a long article about renewable energy. What is the best way to share it in a three-minute presentation?", {"A": "Choose the main claim, two supporting details, and one conclusion.", "B": "Read every sentence as quickly as possible.", "C": "Show the URL and say nothing else.", "D": "Copy the article into every slide."}, "A", "A selects a manageable structure for the time limit while preserving the article's main evidence and conclusion.", "依時間限制整理主張、證據與結論，不把全文搬到簡報。", ["圈出 three-minute presentation 與 long article。", "判斷需要縮減並保留核心關係。", "檢查 A 的 main claim、two details、conclusion 結構。", "排除 B、C、D，因為它們過快朗讀、只貼連結或大量複製。", "選 A，確認內容可在時間內清楚分享。"], "medium"),
make(4, "Which action respects copyright when using an online photograph in a class presentation?", {"A": "Use a permitted image, credit its creator, and include the source.", "B": "Remove the creator's name so the slide looks cleaner.", "C": "Assume every image online is free to copy.", "D": "Use the image and claim that you took it."}, "A", "Permission and clear credit respect the creator's rights and make the image source transparent.", "先確認使用權，再以作者與來源標示建立可追溯分享。", ["確認題目問的是 online photograph 的合法使用。", "找同時包含 permission、creator credit 與 source 的選項。", "檢查 A 三項都能降低侵權與誤認風險。", "排除 B、C、D，因為它們刪署名、錯誤假設或冒充作者。", "選 A，確認素材使用與分享紀錄完整。"], "medium"),
make(5, "A student wants to share a classmate's interview online. What should the student do first?", {"A": "Ask the classmate for permission and agree on what may be shared.", "B": "Post it immediately because the interview was interesting.", "C": "Add the classmate's phone number for context.", "D": "Change the name but keep private details."}, "A", "Permission and agreement about the scope protect the classmate's privacy before public sharing.", "把分享行動與當事人同意、公開範圍及隱私風險一起檢查。", ["辨認素材包含 classmate 的 interview，可能有個人資訊。", "找先取得 permission 並約定 scope 的行動。", "檢查 A 是否在發布前處理同意與可公開內容。", "排除 B、C、D，因為它們未同意、暴露電話或保留私人細節。", "選 A，確認分享前先尊重當事人控制權。"], "medium"),
make(6, "A slide shows the results of a survey of 40 students. Which label makes the chart easiest to understand?", {"A": "Favorite after-school activities: number of students (n=40)", "B": "Interesting chart", "C": "Some answers", "D": "Do not ask questions"}, "A", "A identifies the measured topic, unit, and sample size, so the audience can interpret the chart.", "圖表分享要標明主題、單位與樣本數，讓受眾不必猜數據意義。", ["確認 slide 是 survey results of 40 students。", "列出圖表需要的 topic、unit 與 sample size。", "檢查 A 三項資訊完整。", "排除 B、C、D，因為它們模糊或禁止理解，沒有資料標籤。", "選 A，確認標籤能支援正確解讀。"], "medium"),
make(7, "During a resource-sharing talk, a listener asks, 'Where did that number come from?' What is the best response?", {"A": "It came from the survey table on slide 3; I can show the source note.", "B": "I do not remember, but it sounds right.", "C": "Please do not ask questions.", "D": "The number came from my imagination."}, "A", "A identifies the exact location of the evidence and offers the source note, making the claim checkable.", "面對追問要指出可定位證據與來源，不用語氣或自信取代查證。", ["圈出 where did that number come from，確認聽眾要求證據位置。", "尋找包含 slide 3 與 source note 的回答。", "檢查 A 能讓聽眾回到表格核對。", "排除 B、C、D，因為它們不確定、拒絕或虛構來源。", "選 A，確認回答把主張連回資料。"], "medium"),
make(8, "A student shares two websites with different claims about sleep. What should the presentation include?", {"A": "Both claims, the evidence each uses, and a cautious conclusion.", "B": "Only the claim that sounds more surprising.", "C": "A single answer without naming either website.", "D": "A vote based on which page has more pictures."}, "A", "Presenting both claims and their evidence allows the audience to see the disagreement and supports a careful conclusion.", "比較衝突來源時呈現雙方證據與結論界線，不用驚奇、圖片或投票代替分析。", ["確認兩個 websites 的 claims 不一致。", "列出公平分享需要的兩組 claim 與 evidence。", "檢查 A 最後保留 cautious conclusion，避免過度斷言。", "排除 B、C、D，因為它們選邊、隱藏來源或使用無關指標。", "選 A，確認分享保留不確定性與可檢核證據。"], "hard"),
make(9, "Which ending best invites useful feedback after a presentation about an English learning app?", {"A": "Which feature was clearest, and what would you improve?", "B": "My presentation is perfect, so no comments are needed.", "C": "Remember the app name and leave now.", "D": "Please rate only the slide color."}, "A", "A asks for feedback on clarity and a specific improvement, giving the audience a useful response frame.", "好的分享結尾要提出與內容相關、可回答且能促成修正的問題。", ["確認主題是 English learning app，而不是單純視覺設計。", "找同時詢問 clarity 與 improvement 的開放問題。", "檢查 A 能取得具體回饋。", "排除 B、C、D，因為它們拒絕回饋、離題或限制成單一顏色。", "選 A，確認問題能支持下一版分享改善。"], "medium"),
make(10, "A group is preparing a webpage about a local park. Which final check best protects the quality of the shared resource?", {"A": "Check facts and links, credit images, remove private data, and test the page with a reader.", "B": "Publish as soon as the title is written.", "C": "Use only decorative emojis and no sources.", "D": "Hide errors so visitors will not notice them."}, "A", "The final check covers accuracy, link function, copyright, privacy, and audience usability.", "把分享發布前的內容、來源、隱私與受眾使用性一次核對。", ["確認 webpage 是要公開給讀者使用的 resource。", "列出 facts、links、image credits、private data 與 reader test。", "檢查 A 是否涵蓋五個品質面向。", "排除 B、C、D，因為它們省略查核、來源或刻意隱藏錯誤。", "選 A，確認發布前所有主要風險都有檢查。"], "hard"),
]

for question in Q:
    (OUT / f"{question['id']}.json").write_text(json.dumps(question, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(Q)} questions")
